-- ============================================================================
-- Text2SQL Demo —— 示例数据（脚本生成，随机种子 20260924，基准日期 2026-09-24）
-- 数据量：省份 14 / 商品 40 / 用户 40 / 订单 300 / 订单明细约 750
-- 执行： mysql -h127.0.0.1 -P3306 -uroot -p < src/main/resources/db/data.sql
-- 一致性：订单总金额 = 明细金额之和；商品件数 = 明细数量之和；
--          商品销量、用户累计消费金额由脚本末尾的 UPDATE 按统一口径回填。
-- ============================================================================

USE `ecommerce`;

DELETE FROM `t_order_item`;
DELETE FROM `t_order`;
DELETE FROM `t_user`;
DELETE FROM `t_product`;
DELETE FROM `t_province`;

-- 省份信息表

-- 商品信息表（sales_count 在文件末尾按订单明细回填）

-- 用户信息表（total_amount 在文件末尾按有效订单回填）

-- 订单表

-- 订单明细表（每笔订单 1~4 个商品）

-- ---------------------------------------------------------------------------
-- 统计字段回填（保证与明细口径一致）
-- ---------------------------------------------------------------------------
-- 用户累计消费金额 = 已付款/已发货/已完成订单的实付金额之和
UPDATE `t_user` u SET u.`total_amount` = (
    SELECT IFNULL(ROUND(SUM(o.`pay_amount`), 2), 0) FROM `t_order` o
    WHERE o.`user_id` = u.`id` AND o.`order_status` IN (2, 3, 4));

-- 商品累计销量 = 有效订单明细中的购买数量之和
UPDATE `t_product` p SET p.`sales_count` = (
    SELECT IFNULL(SUM(i.`quantity`), 0) FROM `t_order_item` i
    JOIN `t_order` o ON o.`id` = i.`order_id`
    WHERE i.`product_id` = p.`id` AND o.`order_status` IN (2, 3, 4));

-- 明细表的订单状态快照回填（冗余列，用于让明细直接按成交口径过滤，避免回表关联订单表）
UPDATE `t_order_item` i JOIN `t_order` o ON o.`id` = i.`order_id`
SET i.`order_status` = o.`order_status`;
